def print_batch_loader(loader):
    batch = next(iter(loader))

    print("Sampled batch:")
    print("Edge index:", batch.edge_index.shape)
    print("Node features:", batch.x.shape)
    print("Edge attributes:", batch.edge_attr.shape)
    print("Edge label index (target edges):", batch.edge_label_index.shape)
    print("Edge labels:", batch.edge_label.shape)

    # Check edge_attr
    print(batch)
    print(batch.edge_index)  # Sampled edges
    print(batch.edge_attr)  # Sampled edge attributes
    print(batch.edge_label_index)  # The edges we are predicting